        { "stepId": "cook-pancakes", "name": "Cook pancakes", "task": "griddle", "replicates": { "count": 3, "mode": "serial", "delay": 0 }, "duration": { "type": "fixed", "seconds": 360 }, "startTrigger": { "type": "afterStep", "stepId": "clean-griddle" } },
